{
  "titre": "Les plantes vertes : besoins et expérience",
  "objectifGeneral": "Concevoir une expérience pour identifier les besoins des plantes vertes",
  "notionsPivots": [
    "l'eau",
    "la lumière",
    "le dioxyde de carbone",
    "le sol",
    "la photosynthèse",
    "les nutriments minéraux",
    "le développement végétal",
    "l'hypothèse scientifique",
    "le protocole expérimental",
    "les conditions contrôlées",
    "l'observation scientifique",
    "les résultats expérimentaux"
  ],
  "etapes": [
    {
      "titre": "Déclencheur : observation initiale",
      "objectif": "Formuler des questions sur les besoins des plantes",
      "cartes": [
        {
          "titre": "Observation d'une plante en classe",
          "objectif": "Décrire l'état d'une plante en classe",
          "module": "Appariement",
          "palier": "decouverte",
          "duree": 15,
          "consigne": "Observe attentivement une plante verte en classe. Décris son apparence générale en utilisant des termes précis (hauteur, couleur des feuilles, tiges, etc.)."
        },
        {
          "titre": "Questions sur les causes",
          "objectif": "Proposer des hypothèses sur les besoins de la plante",
          "module": "parcours_mur_notes",
          "palier": "decouverte",
          "duree": 20,
          "consigne": "À partir de ton observation, formule au moins trois questions sur ce dont la plante a besoin pour survivre ou pousser. Note tes propositions sur le mur de post-it partagé."
        }
      ]
    },
    {
      "titre": "Appropriation des connaissances de base",
      "objectif": "Identifier les besoins fondamentaux des plantes vertes",
      "cartes": [
        {
          "titre": "Les besoins des plantes vertes",
          "objectif": "Associer les besoins aux définitions correspondantes",
          "module": "DragAndDrop",
          "palier": "decouverte",
          "duree": 25,
          "consigne": "Associe chaque besoin d'une plante verte (lumière, eau, dioxyde de carbone, sol riche) à sa définition ou à son rôle dans l'image proposée."
        },
        {
          "titre": "Bilan des besoins identifiés",
          "objectif": "Synthétiser les informations sur les besoins des plantes",
          "module": "Summary",
          "palier": "entrainement",
          "duree": 10,
          "consigne": "Rédige un court paragraphe de trois phrases minimal pour résumer les quatre besoins principaux des plantes vertes en utilisant les termes du glossaire présenté."
        }
      ]
    },
    {
      "titre": "Lien avec la photosynthèse",
      "objectif": "Comprendre le mécanisme de la photosynthèse",
      "cartes": [
        {
          "titre": "Le processus de photosynthèse",
          "objectif": "Ordonner les étapes de la photosynthèse",
          "module": "SortParagraphs",
          "palier": "entrainement",
          "duree": 20,
          "consigne": "Replace dans l'ordre les paragraphes décrivant les étapes de la photosynthèse à partir des éléments fournis : absorption de lumière, absorption de CO2, libération d'O2, formation de glucose, rôle de l'eau."
        },
        {
          "titre": "Quiz sur la photosynthèse",
          "objectif": "Valider la compréhension du processus",
          "module": "QuizSet",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Réponds au quiz de 5 questions pour vérifier tes connaissances sur la photosynthèse. Les questions portent sur les éléments essentiels du processus."
        }
      ]
    },
    {
      "titre": "Préparation de l'investigation",
      "objectif": "Définir une problématique et des hypothèses",
      "cartes": [
        {
          "titre": "Choix de la problématique",
          "objectif": "Sélectionner une question de recherche",
          "module": "MultipleChoice",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Choisis, parmi trois propositions, la question de recherche sur laquelle ton groupe va travailler pour élaborer une expérience sur les besoins des plantes. Note ton choix et justifie-le en une phrase."
        },
        {
          "titre": "Formulation d'hypothèses",
          "objectif": "Rédiger des hypothèses testables",
          "module": "Essay",
          "palier": "transfert",
          "duree": 20,
          "consigne": "Rédige au moins deux hypothèses précises qui répondent à ta problématique et qui soient testables dans le cadre de l'expérience à concevoir."
        }
      ]
    },
    {
      "titre": "Conception du protocole expérimental",
      "objectif": "Élaborer un protocole scientifique rigoureux",
      "cartes": [
        {
          "titre": "Élaboration du protocole",
          "objectif": "Créer un plan expérimental détaillé",
          "module": "Devoir",
          "palier": "transfert",
          "duree": 25,
          "consigne": "Rédige un protocole expérimental complet en identifiant : les variables testées, les conditions contrôlées, le matériel nécessaire, les étapes à suivre et une durée prévisionnelle. Envoie ton travail au professeur."
        }
      ]
    },
    {
      "titre": "Mise en œuvre de l'expérience",
      "objectif": "Conduire l'expérience prévue",
      "cartes": [
        {
          "titre": "Exécution du protocole",
          "objectif": "Mettre en pratique l'expérience conçue",
          "module": "page",
          "palier": "transfert",
          "duree": 40,
          "consigne": "En groupe, réalisez l'expérience choisie en classe selon le protocole validé par le professeur. Notez soigneusement les observations initiales et les changements survenus pendant l'expérience."
        },
        {
          "titre": "Récolte des résultats",
          "objectif": "Noter les observations et mesures",
          "module": "Essay",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Rédige un compte-rendu détaillé des résultats obtenus pendant l'expérience en respectant le format demandé (observations, mesures, schémas si possibles)."
        }
      ]
    },
    {
      "titre": "Analyse des résultats",
      "objectif": "Interpréter les données recueillies",
      "cartes": [
        {
          "titre": "Traitement des données",
          "objectif": "Organiser et représenter les résultats",
          "module": "Chart",
          "palier": "transfert",
          "duree": 20,
          "consigne": "Crée un tableau ou un graphique pour représenter les données recueillies pendant l'expérience. Justifie le choix de cette représentation."
        },
        {
          "titre": "Interprétation et conclusion",
          "objectif": "Analyser les résultats et conclure",
          "module": "Essay",
          "palier": "transfert",
          "duree": 25,
          "consigne": "Rédige une interprétation des résultats en validant ou invalidant tes hypothèses initiales. Conclus sur ce que t'a appris cette expérience sur les besoins des plantes vertes."
        }
      ]
    },
    {
      "titre": "Restitution et mutualisation",
      "objectif": "Présenter le travail réalisé à la classe",
      "cartes": [
        {
          "titre": "Préparation de la présentation",
          "objectif": "Structurer les éléments à présenter",
          "module": "parcours_etiquette",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Prépare un support de présentation claire présentant : le problème initial, les hypothèses, le protocole, les résultats et les conclusions de ton expérience. Fais valider les grandes lignes par le professeur."
        },
        {
          "titre": "Presentation orale en classe",
          "objectif": "Communiquer les résultats à la classe",
          "module": "parcours_forum",
          "palier": "transfert",
          "duree": 30,
          "consigne": "Présente oralement à la classe les résultats de ton expérience en 5 minutes. À la suite, réponds aux questions de tes camarades sous le post dédié."
        }
      ]
    }
  ]
}
